1	import { db } from "../lib/db";
2	import { debitWallet, InsufficientBalanceError } from "../lib/wallet";
3	import { invoiceCreateData } from "../lib/invoices";
4	import {
5	  PRODUCT_GRACE_DAYS,
6	  PRODUCT_WARN_DAYS,
7	  VOLUME_TERM_MONTHS,
8	  canAfford,
9	  dedupeSince,
10	  emailRenewalCents,
11	  emailRenewalMonths,
12	  graceEndsAt,
13	  money,
14	  needsUpcomingWarning,
15	  nextExpiry,
16	  reclaimAt,
17	  renewalDecision,
18	  volumeRenewalCents,
19	  ymd,
20	} from "../lib/product-billing";
21	
22	/**
23	 * Recurring billing for the add-on products: business email subscriptions and
24	 * block-storage volumes. Until this existed only the *first* period was charged
25	 * at order time and nothing ever renewed — every one of these products was
26	 * silently free after month one.
27	 *
28	 * Policy (mirrors worker/billing.ts so the whole account behaves the same):
29	 *   T-3d   warn the owner if the renewal would fail (no funds / auto-renew off)
30	 *   T+0    charge the wallet, push `expiresAt` forward one term
31	 *   T+0..G still unpaid: keep it running, nag once per dedupe window
32	 *   T+G    enforce — email: status SUSPENDED (mailboxes kept)
33	 *                    volume: DETACHED + VOLUME_DETACH job (data kept)
34	 * Nothing here ever deletes customer data.
35	 *
36	 * The orchestrator (worker/index.ts) calls `productRenewalSweep()` on a timer.
37	 * Every step is individually try/caught so one poisoned row can never abort the
38	 * sweep, and every mutation is a conditional compare-and-swap so a re-run — or
39	 * two workers racing — can never double-charge.
40	 */
41	
42	const LOG = "[product-billing]";
43	
44	/** Thrown inside a renewal transaction when another sweep already handled the row. */
45	class AlreadyHandledError extends Error {
46	  constructor(what: string) {
47	    super(`already handled: ${what}`);
48	    this.name = "AlreadyHandledError";
49	  }
50	}
51	
52	/** Run a sweep phase, swallowing (but logging) any failure so the rest proceeds. */
53	async function phase(name: string, fn: () => Promise<void>): Promise<void> {
54	  try {
55	    await fn();
56	  } catch (e) {
57	    console.error(`${LOG} phase "${name}" failed`, e);
58	  }
59	}
60	
61	/** Run a per-row step; a bad row is logged and skipped, never fatal. */
62	async function step(what: string, fn: () => Promise<void>): Promise<void> {
63	  try {
64	    await fn();
65	  } catch (e) {
66	    console.error(`${LOG} ${what} failed`, e);
67	  }
68	}
69	
70	/** Best-effort notification (a notify failure must never roll back a charge). */
71	async function notify(userId: string, title: string, body?: string, href?: string) {
72	  try {
73	    await db.notification.create({ data: { userId, title, body, href } });
74	  } catch (e) {
75	    console.error(`${LOG} notify failed`, e);
76	  }
77	}
78	
79	/**
80	 * Send a notification at most once per dedupe window, keyed on the entity label
81	 * plus a stable marker phrase in the title (same technique as worker/billing.ts).
82	 */
83	async function notifyOnce(
84	  now: Date,
85	  userId: string,
86	  label: string,
87	  marker: string,
88	  title: string,
89	  body: string,
90	  href: string
91	) {
92	  const already = await db.notification.findFirst({
93	    where: {
94	      userId,
95	      createdAt: { gt: dedupeSince(now) },
96	      AND: [{ title: { contains: label } }, { title: { contains: marker } }],
97	    },
98	    select: { id: true },
99	  });
100	  if (already) return;
101	  await notify(userId, title, body, href);
102	}
