105	// Business email subscriptions
106	// ---------------------------------------------------------------------------
107	
108	const EMAIL_HREF = "/dashboard/email";
109	
110	/** Heads-up for subscriptions expiring soon whose renewal would fail today. */
111	async function emailUpcomingWarnings(now: Date) {
112	  const soon = new Date(now.getTime() + PRODUCT_WARN_DAYS * 86400_000);
113	  const upcoming = await db.emailSubscription.findMany({
114	    where: { status: "ACTIVE", expiresAt: { gt: now, lt: soon } },
115	    include: { emailPlan: true, user: true },
116	  });
117	
118	  for (const sub of upcoming) {
119	    await step(`email warn ${sub.id}`, async () => {
120	      const priceCents = emailRenewalCents(sub.emailPlan);
121	      if (!needsUpcomingWarning({ autoRenew: sub.autoRenew, balanceCents: sub.user.balanceCents, priceCents })) {
122	        return;
123	      }
124	      await notifyOnce(
125	        now,
126	        sub.userId,
127	        sub.domainName,
128	        "email renews soon",
129	        `${sub.domainName} email renews soon — action needed`,
130	        sub.autoRenew
131	          ? `Renewal is ${money(priceCents)} but your balance is ${money(sub.user.balanceCents)}. Top up before ${ymd(sub.expiresAt!)} to keep your mailboxes delivering.`
132	          : `Auto-renew is off. Renew manually before ${ymd(sub.expiresAt!)} to avoid suspension.`,
133	        EMAIL_HREF
134	      );
135	    });
136	  }
137	}
138	
139	/**
140	 * Charge + extend one subscription atomically.
141	 *
142	 * The compare-and-swap on `expiresAt` is the double-charge guard: the update
143	 * only matches while the row still carries the *old* expiry we based the
144	 * decision on, so a concurrent (or repeated) sweep matches zero rows, throws,
145	 * and rolls the whole transaction — wallet debit included — back.
146	 * Returns true when this call is the one that actually renewed.
147	 */
148	async function chargeEmailRenewal(
149	  sub: { id: string; userId: string; domainName: string; expiresAt: Date | null },
150	  planName: string,
151	  priceCents: number,
152	  newExpiry: Date
153	): Promise<boolean> {
154	  try {
155	    await db.$transaction(async (tx) => {
156	      const advanced = await tx.emailSubscription.updateMany({
157	        where: { id: sub.id, status: "ACTIVE", expiresAt: sub.expiresAt },
158	        data: { expiresAt: newExpiry },
159	      });
160	      if (advanced.count === 0) throw new AlreadyHandledError(`email ${sub.id}`);
161	
162	      if (priceCents > 0) {
163	        await debitWallet(tx, sub.userId, priceCents);
164	        await tx.walletTransaction.create({
165	          data: {
166	            userId: sub.userId,
167	            amountCents: -priceCents,
168	            description: `Business Email renewal: ${planName} for ${sub.domainName}`,
169	          },
170	        });
171	        // PAID invoice, inside the CAS-guarded tx — a repeated sweep matches zero
172	        // rows, throws AlreadyHandledError, and rolls this invoice back too.
173	        await tx.invoice.create({
174	          data: invoiceCreateData({
175	            userId: sub.userId,
176	            description: `Business Email renewal: ${planName} for ${sub.domainName}`,
177	            status: "PAID",
178	            period: { start: sub.expiresAt, end: newExpiry },
179	            lineItems: [
180	              { description: `${planName} — ${sub.domainName}`, qty: 1, unitCents: priceCents, amountCents: priceCents },
181	            ],
182	          }),
183	        });
184	      }
185	      await tx.auditLog.create({
186	        data: {
187	          userId: sub.userId,
188	          action: "billing.renewed",
189	          detail: `email ${sub.id} ${sub.domainName} ${money(priceCents)} -> ${ymd(newExpiry)}`,
190	        },
191	      });
192	    });
193	    return true;
194	  } catch (e) {
195	    if (e instanceof AlreadyHandledError) {
196	      console.log(`${LOG} email ${sub.id} already renewed by another pass — skipping`);
197	      return false;
198	    }
199	    if (e instanceof InsufficientBalanceError) {
200	      // Balance was spent between the read and the debit; the warn/grace path
201	      // picks it up on the next sweep.
202	      console.log(`${LOG} email ${sub.id} lost the race for funds — retrying next sweep`);
203	      return false;
204	    }
205	    throw e;
206	  }
207	}
