302	  const upcoming = await db.volume.findMany({
303	    where: { status: { in: BILLABLE_VOLUME_STATUSES }, expiresAt: { gt: now, lt: soon } },
304	    include: { user: true },
305	  });
306	
307	  for (const volume of upcoming) {
308	    await step(`volume warn ${volume.id}`, async () => {
309	      const priceCents = volumeRenewalCents(volume);
310	      if (canAfford(volume.user.balanceCents, priceCents)) return;
311	      await notifyOnce(
312	        now,
313	        volume.userId,
314	        volume.name,
315	        "volume renews soon",
316	        `Volume "${volume.name}" renews soon — action needed`,
317	        `Renewal is ${money(priceCents)}/mo but your balance is ${money(volume.user.balanceCents)}. Top up before ${ymd(volume.expiresAt!)} — an unpaid volume is detached from its server (your data is kept).`,
318	        VOLUME_HREF
319	      );
320	    });
321	  }
322	}
