458	/** Renew / warn / detach every billable volume that is past its expiry. */
459	async function volumeDueSweep(now: Date) {
460	  const due = await db.volume.findMany({
461	    where: { status: { in: BILLABLE_VOLUME_STATUSES }, expiresAt: { not: null, lt: now } },
462	    include: { user: true },
463	  });
464	
465	  for (const volume of due) {
466	    await step(`volume renewal ${volume.id}`, async () => {
467	      if (!volume.expiresAt) return;
468	      const priceCents = volumeRenewalCents(volume);
469	      const action = renewalDecision({
470	        expiresAt: volume.expiresAt,
471	        now,
472	        autoRenew: true, // volumes have no opt-out; they renew until deleted
473	        balanceCents: volume.user.balanceCents,
474	        priceCents,
475	      });
476	
477	      if (action === "renew") {
478	        const newExpiry = nextExpiry(volume.expiresAt, now, VOLUME_TERM_MONTHS);
479	        const renewed = await chargeVolumeRenewal(volume, priceCents, newExpiry);
480	        if (!renewed) return;
481	        await notify(
482	          volume.userId,
483	          `Volume "${volume.name}" renewed`,
484	          `Charged ${money(priceCents)} for ${volume.sizeGB} GB. Next renewal ${ymd(newExpiry)}.`,
485	          VOLUME_HREF
486	        );
487	        console.log(`${LOG} renewed volume ${volume.id} until ${newExpiry.toISOString()}`);
488	        return;
489	      }
490	
491	      if (action === "enforce") {
492	        await detachUnpaidVolume(volume, priceCents, now);
493	        return;
494	      }
495	
496	      // Inside grace — the volume stays attached and usable; nag once.
497	      await notifyOnce(
498	        now,
499	        volume.userId,
500	        volume.name,
501	        "volume renewal failed",
502	        `Volume "${volume.name}" renewal failed — top up to keep it attached`,
503	        `We couldn't charge ${money(priceCents)} (balance ${money(volume.user.balanceCents)}). The volume stays attached until ${ymd(graceEndsAt(volume.expiresAt, PRODUCT_GRACE_DAYS))}, then it is detached from your server. Your data is never deleted automatically.`,
504	        VOLUME_HREF
505	      );
506	    });
507	  }
508	}
509	
510	// ---------------------------------------------------------------------------
511	
512	/**
513	 * Renewal sweep for the add-on products. Safe to call as often as you like:
514	 * each phase only acts on rows whose `expiresAt` is genuinely in the past, and
515	 * every charge advances `expiresAt` in the same transaction, so repeated runs
516	 * are no-ops rather than repeat charges.
517	 *
518	 * Wire into the worker loop next to `billingSweep()` (see worker/index.ts).
519	 */
520	export async function productRenewalSweep(): Promise<void> {
521	  const now = new Date();
522	  await phase("email upcoming warnings", () => emailUpcomingWarnings(now));
523	  await phase("email renewals", () => emailDueSweep(now));
524	  await phase("volume upcoming warnings", () => volumeUpcomingWarnings(now));
525	  await phase("volume renewals", () => volumeDueSweep(now));
526	}
