598	  // Charge the IP surcharge based on the ACTUAL allocated IP (matching worker/
599	  // billing.ts), not the intent flag — a NAT-fallback server never gets billed.
600	  const hasDedicatedIp = !!(await db.dedicatedIp.findFirst({
601	    where: { serverId }, select: { id: true },
