604	  // like worker/billing.ts — the two renewal paths must never disagree.
605	  const extraDiskMonthly = await extraDiskMonthlyCents(server.extraDiskGB);
606	  const extraDiskCents = extraDiskMonthly * term.months;
607	  const renewCents =
608	    vpsTermPriceCents(plan.priceCents, term.months) +
609	    (hasDedicatedIp ? (await dedicatedIpMonthlyCents()) * term.months : 0) +
610	    extraDiskCents;
